CREATE OR REPLACE TRIGGER trig_check_stock
BEFORE UPDATE OF nb_stock ON produit
FOR EACH ROW
BEGIN
  IF :new.nb_stock < 0 THEN
    RAISE_APPLICATION_ERROR(-20012, 'Stock négatif interdit');
  END IF;
END;

CREATE OR REPLACE TRIGGER trig_id_eleve
BEFORE INSERT ON eleve
FOR EACH ROW
BEGIN
  :new.id_eleve := seq_id_eleve.NEXTVAL;
  :new.date_ajout := SYSDATE;
END;
